export function translateText(source, language) {
  if (language !== 'de') return source;
  const text = source.trim();
  let translated = dictionary[text];
  // The shared widget appends this warning to a consent status in one text node.
  // Match only known copy so drafts and server receipt IDs stay untouched.
  for (const key of ['on', 'off', 'blocked']) {
    if (text === `${NOTICES.en[key]} ${NOTICES.en.pageOnly}`)
      translated = `${NOTICES.de[key]} ${NOTICES.de.pageOnly}`;
  }
  if (translated === undefined) {
    const rules = [
      [/^Feedback saved\. Receipt ID: (.+)$/, (_, id) => NOTICES.de.sent + id],
      [/^Page (\d+) of (\d+)$/, (_, n, total) => `Seite ${n} von ${total}`],
      [/^(\d+) of (\d+) pages reviewed$/, (_, n, total) => `${n} von ${total} Seiten geprüft`],
      [/^Checking PDF page (\d+) of (\d+)…$/, (_, n, total) => `PDF-Seite ${n} von ${total} wird geprüft …`],
      [/^Rendering PDF page (\d+)…$/, (_, n) => `PDF-Seite ${n} wird dargestellt …`],
      [/^Flattening PDF page (\d+) of (\d+)…$/, (_, n, total) => `PDF-Seite ${n} von ${total} wird gerastert …`],
      [/^(.*) px · 150 DPI$/, (_, size) => `${size} px · 150 dpi`],
      [/^(\d+) opaque masks?$/, (_, n) => `${n} deckende ${n === '1' ? 'Maske' : 'Masken'}`],
      [/^Mask (\d+)$/, (_, n) => `Maske ${n}`],
      [/^Remove mask (\d+)$/, (_, n) => `Maske ${n} entfernen`],
      [/^Mask (\d+) added\. Solid black pixels will replace this region\.$/, (_, n) => `Maske ${n} hinzugefügt. Deckend schwarze Pixel ersetzen diesen Bereich.`],
      [/^PNG downloaded with (\d+) opaque masks?\. Review the downloaded image before sharing\.$/, (_, n) => `PNG mit ${n} deckenden ${n === '1' ? 'Maske' : 'Masken'} heruntergeladen. Prüfe das heruntergeladene Bild vor dem Teilen.`],
      [/^(.*) px · original resolution$/, (_, size) => `${size} px · Originalauflösung`],
      [/^(\d+)% smaller$/, (_, n) => `${n} % kleiner`],
      [/^(.*) · under (.*)$/, (_, size, limit) => `${size} · unter ${limit}`],
      [/^Finding a good fit… (.*)$/, (_, size) => `Passende Größe wird ermittelt … ${size}`]
    ];
    for (const [pattern, replacement] of rules) if (pattern.test(text)) { translated = text.replace(pattern, replacement); break; }
  }
  return translated === undefined ? source : source.replace(text, () => translated);
}
